    "description": "1.负责输入法打字拼音召回、排序、联想等核心算法研发与迭代，基于大模型技术持续优化用户输入体验与核心算法指标；\r\n2.独立拆解业务需求与用户体验痛点，负责大模型场景化算法方案设计、选型、落地与迭代，解决输入准确率不足、个性化适配弱、推理延迟高等核心问题；\r\n3.主导大模型轻量化落地工作，涵盖模型微调、量化蒸馏、Prompt优化、RAG应用、端侧推理优化等，平衡算法效果、推理速度与落地成本，保障线上稳定高效运行；\r\n4.负责算法全生命周期闭环，包含数据挖掘分析、bad case归因、模型训练、实验验证、灰度上线、效果复盘迭代，以数据驱动持续优化算法能力；\r\n5.跟进NLP与大模型前沿技术，结合输入法业务场景开展技术创新与专项攻坚，沉淀可复用的技术方法论与优化体系；\r\n6.配合团队完成技术规划与项目推进，协助带教校招新人，规范模块研发流程，赋能团队整体技术能力提升。",
