    "description": "1.多模态内容理解与违规识别：构建融合商品标题文本、主图/详情图、视频素材、商家资质文件等多模态信息的理解与审核算法，实现对违禁商品、资质不符、山寨侵权等风险的自动化精准识别；\r\n2.业务大模型研发与训练：基于电商入驻审核场景的海量数据，将商品、店铺等垂类审核知识注入基础大模型，通过指令微调（SFT）、偏好对齐（RLHF/DPO）、CoT推理等技术，训练具备精准识别垂类违规能力的业务大模型，持续提升机审决策率与准确率；\r\n3.人机协同提效：设计机审辅助人审的技术方案，通过置信度分层、违规线索高亮、审核理由自动生成、难例智能路由等机制，为人审团队提供结构化决策支持，全面提升人工审核效率与准确度；\r\n4.审核系统基建优化：持续优化微信电商入驻审核系统的工程架构，提升审核链路的可用性、时效性与吞吐能力，保障审核服务在高并发场景下的稳定运行；\r\n5.数据闭环与效果监控：建立模型评测基准与效果监控体",
