    "description": "1.负责小游戏/休闲游戏场景下 AI Bot / AI 智能体的算法研发，并落地到真实对局；\r\n2.基于大模型（LLM）、多模态与强化学习技术，研发通用游戏智能体架构，实现拟人化的陪玩机器人、对战对手与 NPC 行为，支持难度分级与风格多样化；\r\n3.针对小游戏低延迟、端侧资源受限的特点，推进模型轻量化与低时延推理优化，并搭建对局数据合成、仿真环境及 Bot 能力评测体系；\r\n4.与策划、客户端、引擎团队协作，完成 Bot 从方案设计到上线的全流程，并持续迭代优化。",
