    "description": "1.深入零售、农业、文旅、酒店、地产、金融交易等行业客户的核心业务流程与商业模式，识别可被AI重塑的关键场景，主导跨团队协作完成科技/AI解决方案的提炼与专项研究，产出面向高层的综合分析与洞察；\r\n2.具备将行业洞察转化为技术方案的能力——理解AI/大模型能力边界，能与产品、研发团队共创解决方案架构，推动从\"咨询建议\"到\"可交付产品\"的落地；\r\n3.基于海量数据进行分析与建模，形成对客户具有决策价值的商业分析与解决方案设计；\r\n4.通过一线调研与客户深度访谈，挖掘企业客户尚未言明的真实需求，提出兼具商业逻辑与技术可行性的创新方案。",
