    "description": "1.领域研究与规划：基于区块链、稳定币等新领域，在海外市场完成竞品与用户研究。推演产品路线图和版本节奏；输出 PRD，写清功能、体验、安全和性能指标；\r\n2.链上体验设计：把地址、Gas、签名、跨链等概念收进产品底层。基于账户抽象（例如EIP-7702）设计免 Gas、批量交易、密钥托管与恢复等方案，降低用户使用门槛；\r\n3.资金与支付链路：设计法币与稳定币之间的流转和兑换逻辑，负责付款、收款、换汇等核心链路，并对接资金账户、支付通道等外部合作方；\r\n4.架构与安全协同：和技术团队一起定义客户端、服务端、合作方系统之间的调用边界和权限模型，参与链基础设施的选型评估；\r\n5.合规落地：和法务合规团队一起，把牌照要求、KYC/AML、Travel Rule 等监管规则转化为产品流程；\r\n6.上线与增长：制定上线策略，联合运营和市场团队推动用户获取和留存，依据数据持续迭代。",
    "requirements": "",
    "jobCode": "2113520440210272256"
