    "description": "1.采购供应系统产品设计/架构师，负责采购供应流程的系统设计、产品规划与业务架构设计，深入理解询价、合同、下单、验收等全链路的业务逻辑，推动采购行业经验沉淀为标准化的流程与规则；\n2.具备强的全局拉通能力，应对复杂的采购供应链路，拥有优秀的通用和局部架构设计能力；牵头联动业务、研发团队，完成采购功能的原型设计、需求拆解及落地迭代，保障系统功能与采购业务场景的高度适配；\n3.负责采购供应相关功能的需求调研、用户反馈收集，结合业务数据迭代优化产品方案，沉淀采购行业经验与最佳实践，提升采购供应效率、降低运营成本；\n4.推动采购产品在服务器/数据中心品类的规模化应用，制定功能落地标准及验收指标，联动跨部门协同推进项目，确保产品功能按期交付并产生业务价值。",
