    "description": "1.负责 AI 数据平台相关产品能力建设，包括数据接入、数据资产管理、数据集管理、权限审批、数据治理、数据消费等方向，提升数据在AI模型研发场景下的流转效率和使用体验；\n2.深入理解 AI 研发、数据生产、数据治理、数据消费等业务流程，抽象共性需求，设计平台化、标准化、可复用的产品方案；\n3.负责数据资产体系建设，包括元数据管理、标签分类、数据详情、数据质量、数据血缘、生命周期管理、使用记录追溯等能力设计；\n4.负责数据权限与安全管控相关产品设计，包括数据分级、访问申请、授权审批、权限控制、审计追踪等机制，保障数据流转过程安全、合规、可管理；\n5.协同算法、研发、数据、安全、运营等团队，完成需求调研、方案设计、原型输出、项目推进、验收上线和持续迭代；\n6.关注 AI 数据工程、数据治理、数据平台、模型训练数据管理等方向的发展趋势，结合业务需求持续优化平台能力和产品体验。",
