    "description": "1.信贷策略设计与优化；\r\n2.围绕分付业务贷前及贷中风险管理需求，开展准入策略、风险分层策略、现金贷额度管理、风险管理策略等设计与迭代；\r\n3.基于用户特征、行为表现及资产质量变化，制定风险识别、策略优化、风险处置方案，持续提升策略有效性；\r\n4.风险分析与策略诊断；\r\n5.围绕资产表现、用户生命周期、风险指标等开展分析，识别风险变化趋势及关键风险因素；\r\n6.结合数据分析、规则策略及模型分析结果，定位风险问题原因，输出策略调整方向，并推动策略落地；\r\n7.风险管理与预警；\r\n8.参与风险监控体系建设，跟踪用户还款表现、风险迁移及资产质量变化；\r\n9.及时发现风险异常，开展风险归因分析，并制定相应风险控制及处置策略；\r\n10.策略效果评估与迭代；\r\n11.通过数据分析、策略回溯、实验验证等方式评估策略效果；\r\n12.持续优化策略规则、风险分层及管理机制，提升风险管理精细化水平。",
