    "description": "1.网赚与福利体系战略规划：负责微视网赚玩法与用户福利体系的整体架构设计，制定中长期发展路线图。结合短视频场景与用户行为，构建具有吸引力的任务激励、金币体系、现金提现、权益兑换等机制，持续提升用户活跃度、留存与时长；\r\n2.深度洞察用户需求与市场趋势：深入研究下沉市场与用户的动机与偏好，设计分层、动态的激励策略。通过数据驱动与ABtest，持续优化用户从任务参与、奖励获取到提现唤回的全链路转化效率，平衡用户增长与成本控制；\r\n3.跨部门协同与落地推动：主导网赚福利产品的全流程落地，高效协同运营、技术、设计、风控、财务等团队，整合资源确保项目高质量交付与迭代。推动奖励供应链（如礼品、现金、虚拟权益）的稳定履约，保障用户体验与资金安全。",
