    "description": "1.负责 MaaS 资源经营规划：建立\"算力资源 → Token 容量 → 收入与成本\"的经营模型，制定资源利用率、售卖率、单位成本、毛利等经营目标与季度经营计划，并对结果负责；\n2.负责资源的产品化与售卖策略：将独立资源（专属实例 / 算力单元）、分级Token（不同服务等级）、预约Token（容量预留 / TPM 保障包）、批量推理等接入形态，抽象为标准化产品规格，设计各形态的定价、可售额度与组合售卖策略；\n3.设计 MaaS 服务等级体系：定义时延、吞吐、可用性、优先级等服务等级，以及准入与配额、抢占与降级、隔离与超卖策略和对应的 SLA 承诺，让服务等级成为可定价、可承诺、可对账的经营杠杆；\n4.以经营收益为目标做全局资源优化：结合需求预测、客户价值、市场竞争与资源成本，制定资源分配、在离线错峰、跨池调拨与价格联动策略，在收入、成本与履约风险之间找到最优解；\n5.主导资源经营后台建",
