    "description": "1.负责 WorkBuddy Agent 业务的数据体系建设，包括数据采集、清洗、建模、加工、存储及数据服务，持续完善业务数仓与指标体系；\r\n2.深入理解智能体产品业务场景，围绕用户增长、活跃、留存、转化、Agent 使用行为、任务完成情况等核心方向开展数据分析，能够从数据中发现问题、定位原因并提出业务优化建议；负责核心业务指标、用户行为分析体系及专题分析建设，对数据变化具备较强敏感度，能够主动识别异常、趋势和潜在业务机会；\r\n3.设计和优化数仓分层、主题域及数据模型，建设稳定、高效、易用的数据资产，提升数据开发效率及下游分析体验；与产品、算法、运营及研发团队紧密协作，将业务问题转化为数据问题和技术方案，通过数据分析、实验评估及指标监控支持产品决策和业务迭代；\r\n4.参与实时与离线数据链路建设，包括 Flink、Spark、Kafka 等相关任务开发与性能优化，保障数据链路的稳定性、准确性",
